class CognitiveFixtures {
static bool c00_simple_if(bool a, bool b, bool c, bool d) { if (a) return true; return false; }
static bool c01_nested_if(bool a, bool b, bool c, bool d) { if (a) { if (b) return true; } return false; }
static bool c02_triple_nested_if(bool a, bool b, bool c, bool d) { if (a) { if (b) { if (c) return true; } } return false; }
static bool c03_if_else(bool a, bool b, bool c, bool d) { if (a) return true; else return false; return false; }
static bool c04_if_elif_else(bool a, bool b, bool c, bool d) { if (a) return true; else if (b) return false; else return true; return false; }
static bool c05_three_way_chain(bool a, bool b, bool c, bool d) { if (a) return true; else if (b) return false; else if (c) return true; else return false; return false; }
static bool c06_and_sequence(bool a, bool b, bool c, bool d) { if (a && b) return true; return false; }
static bool c07_or_sequence(bool a, bool b, bool c, bool d) { if (a || b) return true; return false; }
static bool c08_mixed_boolean(bool a, bool b, bool c, bool d) { if (a && b || c && d) return true; return false; }
static bool c09_assigned_boolean(bool a, bool b, bool c, bool d) { bool value = a && b; return value; return false; }
static bool c10_while_loop(bool a, bool b, bool c, bool d) { while (a) { a = false; } return false; }
static bool c11_for_loop(bool a, bool b, bool c, bool d) { for (int i = 0; i < 2; i++) { } return false; }
static bool c12_if_with_loop(bool a, bool b, bool c, bool d) { if (a) { for (int i = 0; i < 2; i++) { } } return false; }
static bool c13_nested_loops(bool a, bool b, bool c, bool d) { for (int i = 0; i < 2; i++) { while (a) { break; } } return false; }
static bool c14_switch_or_match(bool a, bool b, bool c, bool d) { switch (a) { case true: return true; default: return false; } return false; }
static bool c15_switch_nested_if(bool a, bool b, bool c, bool d) { switch (a) { case true: if (b) return true; break; default: return false; } return false; }
static bool c16_try_one_catch(bool a, bool b, bool c, bool d) { try { if (a) return true; } catch (Exception error) { return false; } return false; }
static bool c17_try_two_catches(bool a, bool b, bool c, bool d) { try { if (a) return true; } catch (ArgumentException error) { return false; } catch (Exception other) { return true; } return false; }
static bool c18_recursive_call(bool a, bool b, bool c, bool d) { if (a) return true; return c18_recursive_call(b, a, c, d); return false; }
static bool c19_conditional_expression(bool a, bool b, bool c, bool d) { return a ? true : false; return false; }
static bool c20_nested_conditionals(bool a, bool b, bool c, bool d) { return a ? true : (b ? false : true); return false; }
static bool c21_lambda_decision(bool a, bool b, bool c, bool d) { return new[] { a }.Any(value => { if (value) return true; return false; }); return false; }
static bool c22_if_lambda_decision(bool a, bool b, bool c, bool d) { if (a) return new[] { b }.Any(value => { if (value) return true; return false; }); return false; }
static bool c23_nested_callable(bool a, bool b, bool c, bool d) { System.Func<bool> inner = () => { if (a) return true; return false; }; return inner(); return false; }
static bool c24_comprehension(bool a, bool b, bool c, bool d) { return new[] { a, b }.Where(value => value).Any(); return false; }
static bool c25_labeled_jump(bool a, bool b, bool c, bool d) { outer: while (a) { break; } return false; }
static bool c26_boolean_operator_sequences(bool a, bool b, bool c, bool d) { return a && (b || c); }
static bool c27_language_idiom(bool a, bool b, bool c, bool d) { bool IsTrue(bool value) { return value; } return IsTrue(a); }static bool c28_loop_if_boolean(bool a, bool b, bool c, bool d) { for (int i = 0; i < 2; i++) { if (a && b) return true; } return false; }
static bool c29_else_loop(bool a, bool b, bool c, bool d) { if (a) return true; else { while (b) { break; } } return false; }
}
